function selectedEdgeFoldTarget(first=ref,second=[...picks][0]){let a=entity(first),b=entity(second);if(!a||!b)return 0;let distance=t=>{let f=G.fold(cells,base,t,true,lengths(),geometry.foldOrder),ends=e=>[f[e.face].corners[e.part],f[e.face].corners[(e.part+1)%4]],x=ends(a),y=ends(b),d=(p,q)=>Math.hypot(...G.add(p,G.mul(q,-1)));return Math.min(Math.max(d(x[0],y[0]),d(x[1],y[1])),Math.max(d(x[0],y[1]),d(x[1],y[0])))};let best=0,bestDistance=Infinity;for(let i=0;i<=1000;i++){let t=i/1000,d=distance(t);if(d<bestDistance-1e-8){best=t;bestDistance=d}if(d<1e-6){let lo=Math.max(0,t-.001),hi=t;for(let j=0;j<22;j++){let mid=(lo+hi)/2;if(distance(mid)<1e-6)hi=mid;else lo=mid}return Math.min(1,Math.ceil(hi*5)/5)}}return best}
