function pairColor(id){if(task==='edge'){let index=edgeCompleted.findIndex(pair=>pair.includes(String(id)));return index<0?'':pairPalette[index%pairPalette.length]}if(task!=='vertex')return '';id=String(id);let allPairs=[...vertexSavedPairs,...vertexPairs];let connected=new Set([id]),changed=true;while(changed){changed=false;for(let pair of allPairs)if(pair.some(p=>connected.has(p)))for(let p of pair)if(!connected.has(p)){connected.add(p);changed=true}}let index=allPairs.findIndex(pair=>pair.some(p=>connected.has(p)));if(index<0)return pendingVertex===id?pairPalette[vertexPairs.length%pairPalette.length]:'';return pairVerdicts&&vertexPairs.some(pair=>pair.some(p=>connected.has(p))&&!pairMatches(pair))?'#d71920':pairPalette[index%pairPalette.length]}

