$('activities').innerHTML=tasks.map(([id,title])=>`<button data-task="${id}" class="${id===task?'active':''}">${title}</button>`).join('');$('activities').onclick=e=>{let b=e.target.closest('[data-task]');if(b)setTask(b.dataset.task)};
$('netList').onclick=e=>{let b=e.target.closest('[data-net]');if(!b)return;let change=()=>{netIndex=+b.dataset.net;cells=nets[netIndex];base=2;picks.clear();revealed=false;prepare();defaultRef();library();help();draw();say('전개도 '+(netIndex+1)+'번이야. 새로운 모양도 접어볼까?')};stop();pausedTo=null;progress=0;change()};$('netFilter').onchange=library;
for(let id of ['cube','cuboid'])$(id).onclick=()=>{if(solid===id)return;let change=()=>{solid=id;$(id).classList.add('active');$(id==='cube'?'cuboid':'cube').classList.remove('active');prepare();defaultRef();picks.clear();revealed=false;help();draw();say(id==='cube'?'여섯 면이 모두 같은 정사각형이야.':'서로 마주 보는 면의 크기가 같은 직육면체야. 접어서 비교해 봐.')};stop();pausedTo=null;progress=0;change()};
$('changeRef').onclick=()=>{choosing=!choosing;revealed=false;picks.clear();help();draw();say(choosing?'전개도에서 새로운 기준을 눌러 줘.':$('question').textContent)};
$('clearLinks').onclick=()=>{if(task==='vertex')defaultRef();vertexPairs=[];pairVerdicts=false;revealed=false;help();draw();say('선택을 지웠어. 만나는 짝을 다시 골라 보자.');};
$('check').onclick=()=>{if(['parallel','perpendicular'].includes(task)){if(!picks.size){say('면을 고르면 자동으로 접어서 확인해요.');return}autoCheckParallel();return;}if(task==='vertex'){if(!vertexSavedPairs.length){say('먼저 만나는 두 점을 직접 연결해 주세요.');return;}revealed=true;help();draw();say('직접 연결한 점들이 만나는지 접어서 확인해 봐요.');animateTo(1);return;}if(task==='edge'&&!picks.size)return say('표시된 선분과 만날 것 같은 선분을 먼저 골라 줘.');if(task==='edge'){revealed=true;let correct=expected().length===picks.size&&expected().every(id=>picks.has(id));help();draw();say('선택한 두 선분이 만나는지 접어서 확인해 보자.');let target=selectedEdgeFoldTarget();animateTo(target,()=>{say(correct?'두 선분이 여기서 만나요. 다시 펼쳐서 다음 선분을 살펴볼게요.':'두 선분이 만나지 않네요. 다시 펼쳐서 한 번 더 골라보세요.',correct?'success':'error');hintTimer=setTimeout(()=>{hintTimer=0;animateTo(0,()=>{if(correct)advanceMatchingTarget();else{revealed=false;picks.clear();help();draw();say('다시 골라 보세요.')}})},2000)});return}let answers=expected();let correct=answers.length===picks.size&&answers.every(id=>picks.has(id));if(['edgePerp','edgeParallel'].includes(task)){let relation=task==='edgeParallel'?'평행한':'직각으로 만나는';revealed=true;help();draw();say(correct?'맞았어요! 접어서 '+relation+' 모서리를 확인해 봐요.':'틀렸어요. 먼저 접어서 정답 모서리와 비교해 봐요.',correct?'success':'error');if(correct){tone(true);animateTo(1,()=>say(task==='edgeParallel'?'맞았어요! 표시된 모서리들은 서로 평행해요.':'맞았어요! 표시된 모서리들은 만나서 직각을 이루어요.','success'));}else{const unfoldAnswer=()=>animateTo(0,()=>say(task==='edgeParallel'?'초록색이 정답이에요. 빨간 기준 모서리와 평행한지 비교해 보세요.':'초록색이 정답이에요. 기준 모서리와 만나 직각을 이루는지 비교해 보세요.','error'),.6);animateTo(1,()=>{say('접은 상태에서 빨간 기준과 초록색 정답을 비교해 보세요.','error');hintTimer=setTimeout(()=>{hintTimer=0;unfoldAnswer()},1500)});}return;}if(!correct){revealed=true;help();draw();say('틀렸어요. 접어서 선택한 답과 정답을 비교해 봐요.','error');animateTo(1,()=>{say('초록색이 정답이에요. 접은 도형에서 비교해 보세요.','error');hintTimer=setTimeout(()=>{hintTimer=0;animateTo(0,()=>say('다시 골라 보세요.','error'),.6)},1500)});return;}revealed=true;help();draw();say(correct?'맞았어요! 수리와 접어서 확인해 봐요.':'같이 확인해 보자. 금색 기준과 초록색 부분을 따라가 봐.',correct?'success':'error');animateTo(1,()=>say((correct?'정답! ':'다시 살펴보자. ')+(kind()==='face'?'기준 면과 관계있는 면은 ':'기준과 만나는 부분은 ')+answers.map(id=>entity(id)?.label).join(' · ')+'. 펼쳐서 위치도 확인해 봐.',correct?'success':'error'));};
function advanceMatchingTarget(){if(task==='vertex'){stop();pausedTo=null;progress=0;let questions=vertexQuestions(),index=questions.findIndex(es=>es.some(e=>e.id===ref));if(index+1<questions.length){ref=questions[index+1][0].id;vertexPairs=[];pendingVertex=null;pairVerdicts=false}else{vertexFinished=true;vertexPairs=[]}picks.clear();revealed=false;help();draw();say(vertexFinished?'모든 만나는 점을 연결했어요! 다음 도형으로 넘어갈게요.':$('question').textContent);if(vertexFinished)hintTimer=setTimeout(()=>{hintTimer=0;$('newQuestion').click()},1500);return}edgeFlash=false;if(task==='edge'){stop();pausedTo=null;progress=0;let questions=edgeQuestions(),index=questions.findIndex(es=>es.some(e=>e.id===ref));if(index+1<questions.length){ref=questions[index+1][0].id}else{randomNet();defaultRef()}edgeFlash=true;picks.clear();revealed=false;help();draw();say('이제 옆의 모서리를 살펴보자. '+$('question').textContent);return}stop();pausedTo=null;progress=0;choosing=false;randomNet();defaultRef();let list=entities();if(task==='vertex'||task==='edge')list=list.filter(e=>entities().some(o=>o.id!==e.id&&o.closedKey===e.closedKey));let alternatives=list.filter(e=>e.id!==ref);ref=(alternatives[Math.floor(Math.random()*alternatives.length)]||list[0]).id;referenceFloor();picks.clear();revealed=false;help();draw();say($('question').textContent)}
$('play').onclick=()=>{tone();if(task==='base'&&!baseChosen){say('먼저 바닥면을 선택해줘.');return;}if(['parallel','perpendicular','edgePerp','edgeParallel'].includes(task)){$('check').click();return;}if(task==='edge'){let questions=edgeQuestions(),index=questions.findIndex(es=>es.some(e=>e.id===ref)),pair=questions[Math.max(0,index-1)];if(!pair)return;let target=selectedEdgeFoldTarget(pair[0].id,pair[1].id);say(pair.map(e=>e.label).join('번과 ')+'번이 만나는 순간까지만 접어볼게요. 지금 문제의 빨간 선분을 살펴보세요.');animateTo(target,()=>{say('여기까지만 접어요. 굵은 빨간 선분은 지금 찾을 선분이에요.');hintTimer=setTimeout(()=>{hintTimer=0;animateTo(0,()=>{edgeFlash=true;help();draw();say('한 번 깜빡인 굵은 선분과 만나는 선분을 골라보세요.');})},2000)});return}animateTo(1)};$('unfold').onclick=()=>animateTo(0);$('pause').onclick=()=>{if(anim){let to=anim.to;stop();pausedTo=to;draw();say('잠깐 멈췄어. 슬라이더로 움직이거나 다시 재생해 봐.')}else animateTo(pausedTo??(progress>=.999?0:1))};$('progress').oninput=e=>{stop();progress=+e.target.value/1000;draw()};$('speed').onchange=()=>{if(anim){let to=anim.to;animateTo(to)}};$('home').onclick=()=>{yaw=-.35;pitch=.82;draw()};
$('flat').onclick=e=>{let hit=e.target.closest('[data-id]');if(hit)select(hit.dataset.id)};
$('scene').onpointerdown=e=>{if(e.button!==0)return;let hit=e.target.closest('[data-id]');drag={x:e.clientX,y:e.clientY,yaw,pitch,id:hit?.dataset.id,moved:false};$('scene').setPointerCapture(e.pointerId)};
$('scene').onpointermove=e=>{if(!drag)return;let dx=e.clientX-drag.x,dy=e.clientY-drag.y;if(Math.hypot(dx,dy)>5)drag.moved=true;if(drag.moved&&progress>.001){yaw=drag.yaw+dx*.009;pitch=Math.max(-1.25,Math.min(1.5,drag.pitch+dy*.008));draw()}};
$('scene').onpointerup=e=>{if(!drag)return;let d=drag;drag=null;if(!d.moved&&d.id!==undefined)select(d.id);suppress=d.moved;setTimeout(()=>suppress=false,0)};$('scene').onpointercancel=()=>drag=null;
window.addEventListener('resize',draw);randomNet();defaultRef();library();help();draw();

for(let id of ['scene','flat'])$(id).addEventListener('keydown',e=>{if(e.key==='Enter'||e.key===' '){let hit=e.target.closest('[data-id]');if(hit){e.preventDefault();select(hit.dataset.id)}}});

$('newQuestion').onclick=()=>{stop();pausedTo=null;progress=0;choosing=false;vertexPairs=[];vertexSavedPairs=[];vertexFinished=false;edgeCompleted=[];picks.clear();revealed=false;randomNet();defaultRef();edgeFlash=task==='edge';help();draw();say($('question').textContent);};

function fitGuideText(){let p=$('message');if(!p||!p.clientWidth)return;let size=22;p.style.fontSize=size+'px';while(size>12&&(p.scrollHeight>76||p.scrollWidth>p.clientWidth+1)){size--;p.style.fontSize=size+'px'}}
new ResizeObserver(fitGuideText).observe(document.querySelector('.suri-guide'));fitGuideText();

function toggleControlPanel(open){document.body.classList.toggle('controls-collapsed',!open);$('toggleControls').setAttribute('aria-expanded',String(open));$('toggleControls').textContent=open?'크게 보기 ⛶':'선택 메뉴 보기 ☰';requestAnimationFrame(draw)}
$('toggleControls').onclick=()=>toggleControlPanel(document.body.classList.contains('controls-collapsed'));
